"""config_drift.py -- diff desired vs live state, emit & apply RFC 6902 patches.

Compares a desired-state JSON config against live state and emits a minimal
patch plan as a list of operations:

    {"op": "add" | "remove" | "replace", "path": "/a/b/0", "value": ...}

Paths are RFC 6902 JSON Pointers ('~' escaped as '~0', '/' as '~1').
Lists are compared by index. ``apply_patch(live, diff(live_desired...))``
round-trips exactly: applying the emitted patch to live yields desired.
"""

from __future__ import annotations

from typing import Any, Dict, List


# --------------------------------------------------------------------------
# JSON Pointer helpers
# --------------------------------------------------------------------------

def _escape(token: str) -> str:
    """Escape a reference token per RFC 6901 (~ -> ~0, / -> ~1)."""
    return token.replace("~", "~0").replace("/", "~1")


def _unescape(token: str) -> str:
    """Inverse of :func:`_escape`."""
    return token.replace("~1", "/").replace("~0", "~")


def _join(prefix: str, token: str) -> str:
    return prefix + "/" + _escape(str(token))


def parse_pointer(pointer: str) -> List[Any]:
    """Parse a JSON pointer into raw tokens (str for dicts, int for lists)."""
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError(f"invalid JSON pointer: {pointer!r}")
    tokens: List[Any] = []
    for raw in pointer[1:].split("/"):
        tokens.append(_unescape(raw))
    return tokens


# --------------------------------------------------------------------------
# Diff
# --------------------------------------------------------------------------

def diff(desired: Any, live: Any) -> List[Dict[str, Any]]:
    """Return the list of ops that transforms ``live`` into ``desired``."""
    ops: List[Dict[str, Any]] = []
    _diff(desired, live, "", ops)
    return ops


def _diff(desired: Any, live: Any, path: str,
          ops: List[Dict[str, Any]]) -> None:
    if isinstance(desired, dict) and isinstance(live, dict):
        for key in sorted(set(live) - set(desired)):
            ops.append({"op": "remove", "path": _join(path, key)})
        for key in sorted(set(desired)):
            if key not in live:
                ops.append({"op": "add", "path": _join(path, key),
                            "value": desired[key]})
            else:
                _diff(desired[key], live[key], _join(path, key), ops)
        return

    if isinstance(desired, list) and isinstance(live, list):
        # Compare common prefix by index.
        for i in range(min(len(desired), len(live))):
            _diff(desired[i], live[i], _join(path, i), ops)
        # Extra live items: remove from the tail so earlier indices stay valid.
        for i in range(len(live) - 1, len(desired) - 1, -1):
            ops.append({"op": "remove", "path": _join(path, i)})
        # Extra desired items: append at the tail.
        for i in range(len(live), len(desired)):
            ops.append({"op": "add", "path": _join(path, i),
                        "value": desired[i]})
        return

    if desired != live:
        if path == "":
            ops.append({"op": "replace", "path": "", "value": desired})
        else:
            ops.append({"op": "replace", "path": path, "value": desired})


# --------------------------------------------------------------------------
# Apply
# --------------------------------------------------------------------------

def _resolve_container(doc: Any, tokens: List[Any]) -> Any:
    """Walk all but the last token; returns (container, last_token)."""
    if not tokens:
        return doc
    cur = doc
    for tok in tokens[:-1]:
        cur = cur[tok] if not isinstance(cur, list) else cur[int(tok)]
    last = tokens[-1]
    if isinstance(cur, list):
        last = int(last)
    return cur, last


def apply_patch(doc: Any, patch: List[Dict[str, Any]]) -> Any:
    """Apply an RFC 6902-style patch (subset: add/remove/replace) to ``doc``.

    Returns the patched document (mutated in place where possible).
    """
    import copy

    doc = copy.deepcopy(doc)
    for op in patch:
        kind = op["op"]
        tokens = parse_pointer(op["path"])
        if kind == "replace":
            if not tokens:
                doc = op["value"]
                continue
            container, last = _resolve_container(doc, tokens)  # type: ignore
            container[last] = op["value"]
        elif kind == "add":
            if not tokens:
                doc = op["value"]
                continue
            resolved = _resolve_container(doc, tokens)
            container, last = resolved
            if isinstance(container, list):
                if last == "-":
                    container.append(op["value"])
                else:
                    container.insert(last, op["value"])
            else:
                container[last] = op["value"]
        elif kind == "remove":
            if not tokens:
                raise ValueError("cannot remove root document")
            container, last = _resolve_container(doc, tokens)  # type: ignore
            del container[last]
        else:
            raise ValueError(f"unsupported op: {kind!r}")
    return doc

