import json
import random

import pytest

from config_drift import apply_patch, diff


def roundtrip(desired, live):
    patch = diff(desired, live)
    assert apply_patch(live, patch) == desired
    return patch


# ---------------------------------------------------------------------------
# Fixed cases
# ---------------------------------------------------------------------------

def test_identical_states_produce_empty_patch():
    state = {"a": [1, {"b": "x"}], "c": None, "d": True}
    assert diff(state, state) == []


def test_scalar_replace():
    patch = roundtrip({"port": 8080}, {"port": 80})
    assert patch == [{"op": "replace", "path": "/port", "value": 8080}]


def test_add_and_remove_keys():
    desired = {"keep": 1, "new": 2}
    live = {"keep": 1, "old": 3}
    patch = roundtrip(desired, live)
    assert {"op": "add", "path": "/new", "value": 2} in patch
    assert {"op": "remove", "path": "/old"} in patch


def test_nested_replace_path():
    desired = {"db": {"host": "h2", "opts": {"tls": True}}}
    live = {"db": {"host": "h1", "opts": {"tls": False}}}
    patch = roundtrip(desired, live)
    assert {"op": "replace", "path": "/db/host", "value": "h2"} in patch
    assert {
        "op": "replace", "path": "/db/opts/tls", "value": True
    } in patch


def test_pointer_escaping():
    # Keys containing '/' and '~' must be escaped (~0, ~1).
    desired = {"weird/key": {"tilde~x": "v"}}
    live = {}
    patch = roundtrip(desired, live)
    paths = [p["path"] for p in patch]
    assert "/weird~1key" in paths
    assert "/weird~1key/tilde~0x" in paths


def test_list_edits_by_index():
    # Replace differing middle element, drop trailing extras.
    desired = [10, 20, 30]
    live = [10, 99, 30, 40, 50]
    patch = roundtrip(desired, live)
    assert {"op": "replace", "path": "/1", "value": 20} in patch
    assert {"op": "remove", "path": "/4"} in patch
    assert {"op": "remove", "path": "/3"} in patch


def test_list_append():
    desired = ["a", "b", "c"]
    live = ["a"]
    patch = roundtrip(desired, live)
    assert {"op": "add", "path": "/1", "value": "b"} in patch
    assert {"op": "add", "path": "/2", "value": "c"} in patch


def test_type_change_is_replace():
    desired = {"x": [1, 2]}
    live = {"x": {"0": 1}}
    patch = roundtrip(desired, live)
    assert patch == [{"op": "replace", "path": "/x", "value": [1, 2]}]


def test_root_replacement():
    assert roundtrip({"a": 1}, [1, 2]) == [
        {"op": "replace", "path": "", "value": {"a": 1}}
    ]


def test_patch_is_json_serializable():
    patch = diff({"a/b": [1]}, {"a/b": [2]})
    json.dumps(patch)  # must not raise


# ---------------------------------------------------------------------------
# Property-style randomized checks (seed 0)
# ---------------------------------------------------------------------------

SCALARS = [None, True, False, 0, 1, -7, 3.14, "", "a", "b/x", "t~k"]


def rand_value(rng, depth=0):
    if depth >= 3 or rng.random() < 0.35:
        return rng.choice(SCALARS)
    if rng.random() < 0.5:
        return {f"k{rng.randrange(5)}": rand_value(rng, depth + 1)
                for _ in range(rng.randrange(4))}
    return [rand_value(rng, depth + 1) for _ in range(rng.randrange(4))]


def test_randomized_diff_apply_roundtrip():
    rng = random.Random(0)
    for trial in range(20):
        desired = rand_value(rng)
        live = rand_value(rng)
        patch = diff(desired, live)
        result = apply_patch(live, patch)
        assert result == desired, f"trial {trial} failed"


def test_randomized_mutated_roundtrip():
    # Mutate one structure slightly: diffs stay small but still round-trip.
    rng = random.Random(0)
    base = rand_value(rng)
    mutated = json.loads(json.dumps(base))
    mutated["k0"] = "changed"
    roundtrip(mutated, base)


if __name__ == "__main__":
    pytest.main([__file__, "-v"])

